export function translateCoreText(locale: Locale, source: string): string {
  if (locale === "en") return source;

  const normalized = source.replace(/\s+/g, " ").trim();
  if (!normalized) return source;

  return (
    (locale === "ms" || locale === "id" || locale === "pt"
      ? newLocaleCuratedText[normalized]?.[locale]
      : undefined) ??
    applicationText[normalized]?.[locale] ??
    generatedTranslations[locale]?.[normalized] ??
    source
  );
}

export function getCoreTextTranslator(locale: Locale) {
  return (source: string) => translateCoreText(locale, source);
}
